# Candidate (B1) for TASK-BANK-021 (idempotency_header_enforcement)
def build_request(data):
    return {
        'path': '/v1/banking/idempotency_header_enforcement/task-bank-021',
        'body': {
            'idempotent_transfer': {
                'amount_subunits': float(data['amount_cents']) / 100.0,
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': 'unverified_route_task-bank-021',
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': 'dropped-idem-b1-task-bank-021'
        }
    }

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
